import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const f=JSON.parse('{"title":"StepperContent","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"Stepper Content"},"headers":[],"relativePath":"guide/components/stepper/stepper-content.md","filePath":"guide/components/stepper/stepper-content.md","lastUpdated":1777448653000}'),c={name:"guide/components/stepper/stepper-content.md"},r=o('<h1 id="steppercontent" tabindex="-1">StepperContent <a class="header-anchor" href="#steppercontent" aria-label="Permalink to &quot;StepperContent&quot;">​</a></h1><p><code>StepperContent</code> is the left-column panel that houses one <code>ue-form</code> per step and a custom preview slot on the final step. It manages local copies of models and schemas to keep updates reactive without unnecessary re-renders.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal sub-component of <code>ue-stepper-form</code>. You do not use it directly.</p></div><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li>Renders a <code>v-stepper-window-item</code> for each entry in <code>forms</code>, each containing a <code>ue-form</code> bound to the corresponding model and schema.</li><li>Forms are mounted lazily: a form only renders once <code>activeStep &gt; i</code> (i.e. the user has reached or passed that step).</li><li>On the final step (<code>value = forms.length + 1</code>) the <code>preview</code> slot is rendered instead of a form.</li><li>The component keeps internal <code>models</code> and <code>localSchemas</code> clones, syncing them with the parent via watchers and emitting <code>update:modelValue</code> / <code>update:schemas</code> when they change.</li><li>The scrollable window (<code>#ue-stepper-content-window</code>) respects <code>maxHeight</code> minus <code>coverHeight</code> so full-width steps can offset for the bottom action bar.</li></ul><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>modelValue</code></td><td><code>Array</code></td><td>Yes</td><td>—</td><td>Array of per-step model objects.</td></tr><tr><td><code>forms</code></td><td><code>Array</code></td><td>Yes</td><td>—</td><td>The <code>forms</code> array from the parent stepper.</td></tr><tr><td><code>schemas</code></td><td><code>Array</code></td><td>Yes</td><td><code>[]</code></td><td>Array of per-step schema arrays.</td></tr><tr><td><code>activeStep</code></td><td><code>Number</code></td><td>Yes</td><td>—</td><td>The currently active 1-based step.</td></tr><tr><td><code>formRefs</code></td><td><code>Array</code></td><td>Yes</td><td>—</td><td>Array of <code>ref</code> handles, one per step, used by the parent for programmatic validation.</td></tr><tr><td><code>isEditing</code></td><td><code>Boolean</code></td><td>No</td><td><code>false</code></td><td>Passed to each <code>ue-form</code> to enable edit mode.</td></tr><tr><td><code>maxHeight</code></td><td><code>String</code></td><td>No</td><td><code>&#39;84vh&#39;</code></td><td>CSS value for the scrollable window&#39;s maximum height.</td></tr><tr><td><code>coverHeight</code></td><td><code>Number</code></td><td>No</td><td><code>0</code></td><td>Pixel height to subtract from <code>maxHeight</code> (e.g. bottom action bar height).</td></tr></tbody></table><h2 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h2><table><thead><tr><th>Event</th><th>Payload</th><th>Description</th></tr></thead><tbody><tr><td><code>update:modelValue</code></td><td><code>Array</code></td><td>Emitted when any step&#39;s model changes.</td></tr><tr><td><code>update:schemas</code></td><td><code>Array</code></td><td>Emitted when any step&#39;s schema changes.</td></tr><tr><td><code>form-input</code></td><td><code>{ event, index }</code></td><td>Forwarded from each <code>ue-form</code>&#39;s <code>input</code> event; <code>index</code> is the 0-based step index.</td></tr><tr><td><code>form-valid</code></td><td><code>{ event, index }</code></td><td>Forwarded from each <code>ue-form</code>&#39;s <code>update:valid</code> event; <code>event</code> is <code>true/false</code>.</td></tr></tbody></table><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table><thead><tr><th>Slot</th><th>Description</th></tr></thead><tbody><tr><td><code>preview</code></td><td>Rendered inside the final step&#39;s <code>v-stepper-window-item</code>. Used by <code>StepperForm</code> to inject <code>StepperPreview</code>.</td></tr></tbody></table>',11),a=[r];function s(n,i,h,p,l,m){return d(),t("div",null,a)}const b=e(c,[["render",s]]);export{f as __pageData,b as default};
